=Você deve analisar o histórico da conversa e identificar se o usuário informou o número de um chamado.

Histórico da conversa:
{{
$('Busca histórico mensagens3').all()
.map(item => item.json)
.map(msg => {
const origem = msg.origem === 'usuario' ? 'Usuário' : msg.origem === 'tecnico' ? 'Técnico' : msg.origem || 'Mensagem';
return `${origem}: ${msg.mensagem || ''}`;
})
.join('\n')
}}

Regras:

* Responda somente em JSON válido.
* Retorne o número do chamado informado pelo usuário na variável `numero_chamado`.
* Não explique nada.
* Não adicione texto antes ou depois do JSON.
* Se houver mais de um número de chamado, retorne o mais recente informado pelo usuário.
* Se o usuário não informou número de chamado, retorne `numero_chamado` vazio.
* Ignore números que não pareçam ser número de chamado, como telefone, data, horário, CPF, CNPJ ou código de erro.

Formato obrigatório da resposta:

{
"numero_chamado": "12345"
}

Se não houver número de chamado:

{
"numero_chamado": ""
}

parameters.jsCode:
const texto = $json.output?.[0]?.content?.[0]?.text || '';

let numeroChamado = '';

try {
  const dados = JSON.parse(texto);
  numeroChamado = dados.numero_chamado || '';
} catch (error) {
  const match = String(texto).match(/\b\d+\b/);
  numeroChamado = match ? match[0] : '';
}

return [
  {
    json: {
      numero_chamado: numeroChamado
    }
  }
];

function limparHtml(texto) {
  if (!texto) return '';

  return String(texto)
    // Converte entidades HTML escapadas
    .replace(/&#60;/g, '<')
    .replace(/&#62;/g, '>')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&#34;/g, '"')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&amp;/g, '&')
    .replace(/&nbsp;/g, ' ')
    .replace(/ /g, ' ')

    // Quebras de linha para fechamento de blocos HTML
    .replace(/<\/p>/gi, '\n')
    .replace(/<\/h1>/gi, '\n')
    .replace(/<\/h2>/gi, '\n')
    .replace(/<\/h3>/gi, '\n')
    .replace(/<br\s*\/?>/gi, '\n')

    // Remove todas as tags HTML restantes
    .replace(/<[^>]*>/g, '')

    // Limpa espaços e quebras excessivas
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

return items.map(item => {
  const tituloDescricao = item.json.titulo_descricao || '';

  return {
    json: {
      id: item.json.id,
      titulo_descricao_limpo: limparHtml(tituloDescricao)
    }
  };
});

